argv:
$ErrorActionPreference='Stop'
$t=Invoke-RestMethod -UseBasicParsing 'http://127.0.0.1:17410/json/list' -TimeoutSec 3
$target=@($t)|Where-Object { try { ([uri]$_.url).Host -eq 'bugbountyfoto6.files.com' } catch { $false } } | Select-Object -First 1
if(-not $target){ throw 'Files.com CDP target not found' }
$ws=[System.Net.WebSockets.ClientWebSocket]::new()
$cts=[System.Threading.CancellationTokenSource]::new()
$cts.CancelAfter(12000)
$ws.ConnectAsync([uri]$target.webSocketDebuggerUrl,$cts.Token).GetAwaiter().GetResult() | Out-Null
$expr=@'
(async()=>{
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  async function get(url){
    const r=await fetch(url,{credentials:'same-origin'});
    const text=await r.text();
    let j=null; try{j=JSON.parse(text)}catch{}
    return {status:r.status, ok:r.ok, text, json:j};
  }
  const out={};
  let x=await get('/api/rest/v1/permissions.json?user_id=0&include_groups=true');
  out.permissions={status:x.status, items:Array.isArray(x.json)?x.json.map(p=>({path:p.path,permission:p.permission,recursive:p.recursive,username:p.username})):[], error:(!x.ok?x.text.slice(0,300):null)};
  await sleep(650);
  x=await get('/api/rest/v1/folders/public-b');
  out.public_b={status:x.status, items:Array.isArray(x.json)?x.json.map(f=>({path:f.path,type:f.type})).slice(0,20):[], error:(!x.ok?x.text.slice(0,300):null)};
  await sleep(650);
  x=await get('/api/rest/v1/folders/private-a');
  out.private_a={status:x.status, items:Array.isArray(x.json)?x.json.map(f=>({path:f.path,type:f.type})).slice(0,20):[], error:(!x.ok?x.text.slice(0,300):null)};
  await sleep(650);
  x=await get('/api/rest/v1/bundles.json?user_id=0');
  out.bundles={status:x.status,count:Array.isArray(x.json)?x.json.length:null,error:(!x.ok?x.text.slice(0,300):null)};
  return JSON.stringify(out);
})()
'@
$payload=@{id=1;method='Runtime.evaluate';params=@{expression=$expr;returnByValue=$true;awaitPromise=$true}}|ConvertTo-Json -Depth 10 -Compress
$bytes=[System.Text.Encoding]::UTF8.GetBytes($payload)
$ws.SendAsync([System.ArraySegment[byte]]::new($bytes),[System.Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult() | Out-Null
$buf=New-Object byte[] 131072
while($true){
  $ms=[System.IO.MemoryStream]::new()
  do {
    $r=$ws.ReceiveAsync([System.ArraySegment[byte]]::new($buf),$cts.Token).GetAwaiter().GetResult()
    if($r.Count -gt 0){ $ms.Write($buf,0,$r.Count) }
  } while(-not $r.EndOfMessage)
  $txt=[System.Text.Encoding]::UTF8.GetString($ms.ToArray())
  $obj=$txt|ConvertFrom-Json
  if($obj.id -eq 1){
    if($obj.result.exceptionDetails){ throw $obj.result.exceptionDetails.text }
    Write-Output $obj.result.result.value
    break
  }
}
$ws.Dispose()
